<?php
namespace App\Services; use App\Models\StudentApplication; use Illuminate\Support\Facades\DB;
class ApplicationStatusService { private const MAP=['submitted'=>['under_review'],'under_review'=>['revision','verified'],'revision'=>['submitted'],'verified'=>['accepted','rejected']]; public function transition(StudentApplication $application,string $to,?string $note,int $userId):void { DB::transaction(function()use($application,$to,$note,$userId){$locked=StudentApplication::lockForUpdate()->findOrFail($application->id);abort_unless(in_array($to,self::MAP[$locked->status]??[],true),422,'Transisi status tidak valid.');if(in_array($to,['revision','rejected'],true))abort_unless(filled($note),422,'Catatan wajib diisi.');$locked->update(['status'=>$to,'verified_at'=>$to==='verified'?now():$locked->verified_at]);$locked->statusHistories()->create(['status'=>$to,'note'=>$note,'changed_by'=>$userId]);});} }
